sealed class NovaCoreException: kotlin.Exception() {
    
    class InvalidUrl(
        
        val `detail`: kotlin.String
        ) : NovaCoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class InvalidPayload(
        
        val `detail`: kotlin.String
        ) : NovaCoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Crypto(
        
        val `detail`: kotlin.String
        ) : NovaCoreException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<NovaCoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): NovaCoreException = FfiConverterTypeNovaCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeNovaCoreError : FfiConverterRustBuffer<NovaCoreException> {
    override fun read(buf: ByteBuffer): NovaCoreException {
        

        return when(buf.getInt()) {
            1 -> NovaCoreException.InvalidUrl(
                FfiConverterString.read(buf),
                )
            2 -> NovaCoreException.InvalidPayload(
                FfiConverterString.read(buf),
                )
            3 -> NovaCoreException.Crypto(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: NovaCoreException): ULong {
        return when(value) {
            is NovaCoreException.InvalidUrl -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is NovaCoreException.InvalidPayload -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is NovaCoreException.Crypto -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: NovaCoreException, buf: ByteBuffer) {
        when(value) {
            is NovaCoreException.InvalidUrl -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is NovaCoreException.InvalidPayload -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is NovaCoreException.Crypto -> {
                buf.putInt(3)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




